using DomainModel.Models; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DomainModel.Configurations; public class FavoriteAdvertisementConfiguration:IEntityTypeConfiguration<FavoriteAdvertisement>{ public void Configure(EntityTypeBuilder<FavoriteAdvertisement>b){ b.HasKey(x=>x.FavoriteAdvertisementID); b.HasIndex(x=>new{x.UserID,x.AdvertisementID}).IsUnique(); b.HasOne(x=>x.User).WithMany(x=>x.FavoriteAdvertisements).HasForeignKey(x=>x.UserID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x=>x.Advertisement).WithMany(x=>x.Favorites).HasForeignKey(x=>x.AdvertisementID).OnDelete(DeleteBehavior.Cascade); }}